### Remove all finalized jobs

The simplest option is to set `removeOnComplete`/`removeOnFail` to `true`, in this case, all jobs will be removed automatically as soon as they are finalized:

{% tabs %}
{% tab title="TypeScript" %}

```typescript
await myQueue.add(
  'test',
  { foo: 'bar' },
  { removeOnComplete: true, removeOnFail: true },
);
```

{% endtab %}

{% tab title="Python" %}

```python
await my_queue.add(
    "test",
    {"foo": "bar"},
    {"removeOnComplete": True, "removeOnFail": True},
)
```

{% endtab %}

{% tab title=".NET" %}

```csharp
await myQueue.AddAsync(
    "test",
    new { foo = "bar" },
    new JobsOptions { RemoveOnComplete = true, RemoveOnFail = true });
```

{% endtab %}

{% tab title="Rust" %}

```rust
use bullmq::types::RemoveOnFinish;

my_queue
    .add("test", serde_json::json!({"foo": "bar"}))
    .remove_on_complete(RemoveOnFinish::Bool(true))
    .remove_on_fail(RemoveOnFinish::Bool(true))
    .await?;
```

{% endtab %}

{% tab title="PHP" %}

```php
<?php

$myQueue->add(
    'test',
    ['foo' => 'bar'],
    ['removeOnComplete' => true, 'removeOnFail' => true],
);
```

{% endtab %}
{% endtabs %}

{% hint style="warning" %}
Jobs will be deleted regardless of their names.
{% endhint %}

### Remove all finalized jobs

The simplest option is to set `removeOnComplete`/`removeOnFail` to `{count: 0}`, in this case, all jobs will be removed automatically as soon as they are finalized:

{% tabs %}
{% tab title="TypeScript" %}

```typescript
const myWorker = new Worker(
  'myQueueName',
  async job => {
    // do some work
  },
  {
    connection,
    removeOnFail: { count: 0 },
  },
);
```

{% endtab %}

{% tab title="Python" %}

```python
from bullmq import Worker

async def process_job(job, token):
    # do some work
    pass

worker = Worker(
    'myQueueName',
    process_job,
    {
        "connection": connection,
        "removeOnFail": {"count": 0},
    },
)
```

{% endtab %}

{% tab title="Elixir" %}

```elixir
{:ok, worker} = BullMQ.Worker.start_link(
  queue: "myQueueName",
  processor: fn _job ->
    # do some work
    :ok
  end,
  connection: :my_redis,
  remove_on_fail: %{count: 0}
)
```

{% endtab %}

{% tab title="Rust" %}

```rust
use bullmq::types::RemoveOnFinish;
use bullmq::worker::CancellationToken;
use bullmq::{Job, Worker, WorkerOptions};

let worker = Worker::with_options(
    "myQueueName",
    |_job: Job, _token: CancellationToken| async move {
        // do some work
        Ok(serde_json::Value::Null)
    },
    WorkerOptions {
        connection,
        remove_on_fail: Some(RemoveOnFinish::Count(0)),
        ..Default::default()
    },
)
.await?;
```

{% endtab %}
{% endtabs %}

{% hint style="warning" %}
Jobs will be deleted regardless of their names.
{% endhint %}
